Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Latent z
  <input type="range" id="latentZ" min="-2" max="2" step="0.05" value="-1.2">
</label>
<button id="btnMarginalize">Marginalize over z</button>
<button id="btnResetObs">Reset observation</button>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* === GEOMETRY SPEC ===
// box wireframe → LineSegments, brown #6b3a1f, box [-1.6,1.6]^2 x [-2,2]
// slice planes → PlaneGeometry(3.2,3.2) at z∈{-1.5,-0.75,0,0.75,1.5}, canvas Gaussian texture, dark maroon
// decoder manifold → TubeGeometry(r=0.025) along f_phi(z), teal #5bc8c8
// sample dots → SphereGeometry(0.055) at f_phi(-1.2) and f_phi(0.8), teal
// dashed arc → Line+LineDashedMaterial, teal, bezier between dots
// marginal plane → PlaneGeometry(3.2,3.2) at x=3.5, rotated -45° Y, canvas banana texture
// projected curve → TubeGeometry on marginal plane, teal
// gray arrow → Line+ConeGeometry, #b0b0b0
// posterior curve → Line along z at bottom of box, teal
// observation marker → SphereGeometry(0.06), teal, draggable
*/

const BROWN = 0x6b3a1f;
const MAROON = 0x2a0d08;
const CREAM = 0xffe9c4;
const TEAL = 0x5bc8c8;
const GRAY = 0xb0b0b0;
const SIGMA = 0.28;

function fPhi(z) {
  return { x: 1.25 * Math.cos(0.85 * z), y: 1.25 * Math.sin(0.85 * z) - 0.2 };
}

// --- Box wireframe ---
const boxMin = new THREE.Vector3(-1.6, -1.6, -2);
const boxMax = new THREE.Vector3(1.6, 1.6, 2);
const boxEdges = [];
const corners = [
  [boxMin.x, boxMin.y, boxMin.z], [boxMax.x, boxMin.y, boxMin.z],
  [boxMax.x, boxMax.y, boxMin.z], [boxMin.x, boxMax.y, boxMin.z],
  [boxMin.x, boxMin.y, boxMax.z], [boxMax.x, boxMin.y, boxMax.z],
  [boxMax.x, boxMax.y, boxMax.z], [boxMin.x, boxMax.y, boxMax.z]
];
const edgePairs = [[0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7],[7,4],[0,4],[1,5],[2,6],[3,7]];
for (const [a, b] of edgePairs) {
  boxEdges.push(new THREE.Vector3(...corners[a]), new THREE.Vector3(...corners[b]));
}
const boxGeom = new THREE.BufferGeometry().setFromPoints(boxEdges);
const boxLine = new THREE.LineSegments(boxGeom, new THREE.LineBasicMaterial({ color: BROWN }));
scene.add(boxLine);

// --- Gaussian texture helper ---
function createGaussianTexture(cx, cy, sigma, size = 128) {
  const canvas = document.createElement('canvas');
  canvas.width = size; canvas.height = size;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#2a0d08';
  ctx.fillRect(0, 0, size, size);
  const px = ((cx + 1.6) / 3.2) * size;
  const py = size - ((cy + 1.6) / 3.2) * size;
  const sigmaPx = (sigma / 3.2) * size;
  const r = sigmaPx * 4;
  const grad = ctx.createRadialGradient(px, py, 0, px, py, r);
  grad.addColorStop(0, 'rgba(255,233,196,1)');
  grad.addColorStop(0.25, 'rgba(212,132,90,0.9)');
  grad.addColorStop(0.5, 'rgba(107,42,21,0.7)');
  grad.addColorStop(1, 'rgba(42,13,8,0)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, size, size);
  const tex = new THREE.CanvasTexture(canvas);
  tex.needsUpdate = true;
  return tex;
}

// --- Slice planes ---
const sliceZs = [-1.5, -0.75, 0, 0.75, 1.5];
const slicePlanes = [];
const sliceGroup = new THREE.Group();
for (const z of sliceZs) {
  const c = fPhi(z);
  const tex = createGaussianTexture(c.x, c.y, SIGMA);
  const mat = new THREE.MeshBasicMaterial({
    map: tex, transparent: true, opacity: 0.85, side: THREE.DoubleSide, depthWrite: false
  });
  const plane = new THREE.Mesh(new THREE.PlaneGeometry(3.2, 3.2), mat);
  plane.position.set(0, 0, z);
  sliceGroup.add(plane);
  slicePlanes.push({ mesh: plane, z });
}
scene.add(sliceGroup);

// Active slice highlight
let activeSliceIdx = 0;
function updateActiveSlice(zVal) {
  let best = 0, bestDist = Infinity;
  slicePlanes.forEach((s, i) => {
    const d = Math.abs(s.z - zVal);
    if (d < bestDist) { bestDist = d; best = i; }
  });
  slicePlanes.forEach((s, i) => {
    s.mesh.material.opacity = (i === best) ? 1.0 : 0.55;
  });
  activeSliceIdx = best;
}
updateActiveSlice(-1.2);

// --- Decoder manifold ---
const manifoldPts = [];
for (let i = 0; i <= 200; i++) {
  const z = -2 + 4 * i / 200;
  const c = fPhi(z);
  manifoldPts.push(new THREE.Vector3(c.x, c.y, z));
}
const manifoldCurve = new THREE.CatmullRomCurve3(manifoldPts);
const tubeGeom = new THREE.TubeGeometry(manifoldCurve, 200, 0.025, 8, false);
const manifoldMesh = new THREE.Mesh(tubeGeom, new THREE.MeshBasicMaterial({ color: TEAL }));
scene.add(manifoldMesh);

// --- Sample dots ---
const dot1Z = -1.2, dot2Z = 0.8;
const c1 = fPhi(dot1Z), c2 = fPhi(dot2Z);
const dot1 = new THREE.Mesh(new THREE.SphereGeometry(0.055, 16, 16), new THREE.MeshBasicMaterial({ color: TEAL }));
dot1.position.set(c1.x, c1.y, dot1Z);
scene.add(dot1);
const dot2 = new THREE.Mesh(new THREE.SphereGeometry(0.055, 16, 16), new THREE.MeshBasicMaterial({ color: TEAL }));
dot2.position.set(c2.x, c2.y, dot2Z);
scene.add(dot2);

// --- Dashed arc between dots ---
const arcPts = [];
const arcN = 60;
for (let i = 0; i <= arcN; i++) {
  const t = i / arcN;
  const x = c1.x + (c2.x - c1.x) * t;
  const y = c1.y + (c2.y - c1.y) * t + 0.6 * Math.sin(Math.PI * t);
  const z = dot1Z + (dot2Z - dot1Z) * t;
  arcPts.push(new THREE.Vector3(x, y, z));
}
const arcGeom = new THREE.BufferGeometry().setFromPoints(arcPts);
const arcMat = new THREE.LineDashedMaterial({ color: TEAL, dashSize: 0.12, gapSize: 0.08 });
const arcLine = new THREE.Line(arcGeom, arcMat);
arcLine.computeLineDistances();
scene.add(arcLine);

// --- Marginal density texture ---
function createMarginalTexture(size = 128) {
  const canvas = document.createElement('canvas');
  canvas.width = size; canvas.height = size;
  const ctx = canvas.getContext('2d');
  const imgData = ctx.createImageData(size, size);
  const nZ = 80;
  const densities = new Float32Array(size * size);
  let maxD = 0;
  for (let py = 0; py < size; py++) {
    for (let px = 0; px < size; px++) {
      const x1 = (px / (size - 1)) * 3.2 - 1.6;
      const x2 = 1.6 - (py / (size - 1)) * 3.2;
      let density = 0;
      for (let i = 0; i < nZ; i++) {
        const z = -2 + 4 * i / (nZ - 1);
        const c = fPhi(z);
        const dx = x1 - c.x, dy = x2 - c.y;
        density += Math.exp(-(dx * dx + dy * dy) / (2 * SIGMA * SIGMA)) * Math.exp(-z * z / 2);
      }
      densities[py * size + px] = density;
      if (density > maxD) maxD = density;
    }
  }
  for (let py = 0; py < size; py++) {
    for (let px = 0; px < size; px++) {
      const idx = py * size + px;
      const t = Math.pow(densities[idx] / maxD, 0.5);
      const r = Math.round(42 + (255 - 42) * t);
      const g = Math.round(13 + (233 - 13) * t);
      const b = Math.round(8 + (196 - 8) * t);
      const pi = idx * 4;
      imgData.data[pi] = r;
      imgData.data[pi + 1] = g;
      imgData.data[pi + 2] = b;
      imgData.data[pi + 3] = 255;
    }
  }
  ctx.putImageData(imgData, 0, 0);
  const tex = new THREE.CanvasTexture(canvas);
  tex.needsUpdate = true;
  return tex;
}

