// sample dots → SphereGeometry(0.055) at f_phi(-1.2) and f_phi(0.8), teal
// dashed arc → Line+LineDashedMaterial, teal, bezier between dots
// marginal plane → PlaneGeometry(3.2,3.2) at x=3.5, rotated -45° Y, canvas banana texture
// projected curve → TubeGeometry on marginal plane, teal
// gray arrow → Line+ConeGeometry, #b0b0b0
// posterior curve → Line along z at bottom of box, teal
// observation marker → SphereGeometry(0.06), teal, draggable
*/

const BROWN = 0x6b3a1f;
const MAROON = 0x2a0d08;
const CREAM = 0xffe9c4;
const TEAL = 0x5bc8c8;
const GRAY = 0xb0b0b0;
const SIGMA = 0.28;

function fPhi(z) {
  return { x: 1.25 * Math.cos(0.85 * z), y: 1.25 * Math.sin(0.85 * z) - 0.2 };
}

// --- Box wireframe ---
const boxMin = new THREE.Vector3(-1.6, -1.6, -2);
const boxMax = new THREE.Vector3(1.6, 1.6, 2);
const boxEdges = [];
const corners = [
  [boxMin.x, boxMin.y, boxMin.z], [boxMax.x, boxMin.y, boxMin.z],
  [boxMax.x, boxMax.y, boxMin.z], [boxMin.x, boxMax.y, boxMin.z],
  [boxMin.x, boxMin.y, boxMax.z], [boxMax.x, boxMin.y, boxMax.z],
  [boxMax.x, boxMax.y, boxMax.z], [boxMin.x, boxMax.y, boxMax.z]
];
const edgePairs = [[0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7],[7,4],[0,4],[1,5],[2,6],[3,7]];
for (const [a, b] of edgePairs) {
  boxEdges.push(new THREE.Vector3(...corners[a]), new THREE.Vector3(...corners[b]));
}
const boxGeom = new THREE.BufferGeometry().setFromPoints(boxEdges);
const boxLine = new THREE.LineSegments(boxGeom, new THREE.LineBasicMaterial({ color: BROWN }));
scene.add(boxLine);

// --- Gaussian texture helper ---
function createGaussianTexture(cx, cy, sigma, size = 128) {
  const canvas = document.createElement('canvas');
  canvas.width = size; canvas.height = size;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#2a0d08';
  ctx.fillRect(0, 0, size, size);
  const px = ((cx + 1.6) / 3.2) * size;
  const py = size - ((cy + 1.6) / 3.2) * size;
  const sigmaPx = (sigma / 3.2) * size;
  const r = sigmaPx * 4;
  const grad = ctx.createRadialGradient(px, py, 0, px, py, r);
  grad.addColorStop(0, 'rgba(255,233,196,1)');
  grad.addColorStop(0.25, 'rgba(212,132,90,0.9)');
  grad.addColorStop(0.5, 'rgba(107,42,21,0.7)');
  grad.addColorStop(1, 'rgba(42,13,8,0)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, size, size);
  const tex = new THREE.CanvasTexture(canvas);
  tex.needsUpdate = true;
  return tex;
}

// --- Slice planes ---
const sliceZs = [-1.5, -0.75, 0, 0.75, 1.5];
const slicePlanes = [];
const sliceGroup = new THREE.Group();
for (const z of sliceZs) {
  const c = fPhi(z);
  const tex = createGaussianTexture(c.x, c.y, SIGMA);
  const mat = new THREE.MeshBasicMaterial({
    map: tex, transparent: true, opacity: 0.85, side: THREE.DoubleSide, depthWrite: false
  });
  const plane = new THREE.Mesh(new THREE.PlaneGeometry(3.2, 3.2), mat);
  plane.position.set(0, 0, z);
  sliceGroup.add(plane);
  slicePlanes.push({ mesh: plane, z });
}
scene.add(sliceGroup);

// Active slice highlight
let activeSliceIdx = 0;
function updateActiveSlice(zVal) {
  let best = 0, bestDist = Infinity;
  slicePlanes.forEach((s, i) => {
    const d = Math.abs(s.z - zVal);
    if (d < bestDist) { bestDist = d; best = i; }
  });
  slicePlanes.forEach((s, i) => {
    s.mesh.material.opacity = (i === best) ? 1.0 : 0.55;
  });
  activeSliceIdx = best;
}
updateActiveSlice(-1.2);

// --- Decoder manifold ---
const manifoldPts = [];
for (let i = 0; i <= 200; i++) {
  const z = -2 + 4 * i / 200;
  const c = fPhi(z);
  manifoldPts.push(new THREE.Vector3(c.x, c.y, z));
}
const manifoldCurve = new THREE.CatmullRomCurve3(manifoldPts);
const tubeGeom = new THREE.TubeGeometry(manifoldCurve, 200, 0.025, 8, false);
const manifoldMesh = new THREE.Mesh(tubeGeom, new THREE.MeshBasicMaterial({ color: TEAL }));
scene.add(manifoldMesh);

// --- Sample dots ---
const dot1Z = -1.2, dot2Z = 0.8;
const c1 = fPhi(dot1Z), c2 = fPhi(dot2Z);
const dot1 = new THREE.Mesh(new THREE.SphereGeometry(0.055, 16, 16), new THREE.MeshBasicMaterial({ color: TEAL }));
dot1.position.set(c1.x, c1.y, dot1Z);
scene.add(dot1);
const dot2 = new THREE.Mesh(new THREE.SphereGeometry(0.055, 16, 16), new THREE.MeshBasicMaterial({ color: TEAL }));
dot2.position.set(c2.x, c2.y, dot2Z);
scene.add(dot2);

// --- Dashed arc between dots ---
const arcPts = [];
const arcN = 60;
for (let i = 0; i <= arcN; i++) {
  const t = i / arcN;
  const x = c1.x + (c2.x - c1.x) * t;
  const y = c1.y + (c2.y - c1.y) * t + 0.6 * Math.sin(Math.PI * t);
  const z = dot1Z + (dot2Z - dot1Z) * t;
  arcPts.push(new THREE.Vector3(x, y, z));
}
const arcGeom = new THREE.BufferGeometry().setFromPoints(arcPts);
const arcMat = new THREE.LineDashedMaterial({ color: TEAL, dashSize: 0.12, gapSize: 0.08 });
const arcLine = new THREE.Line(arcGeom, arcMat);
arcLine.computeLineDistances();
scene.add(arcLine);

// --- Marginal density texture ---
function createMarginalTexture(size = 128) {
  const canvas = document.createElement('canvas');
  canvas.width = size; canvas.height = size;
  const ctx = canvas.getContext('2d');
  const imgData = ctx.createImageData(size, size);
  const nZ = 80;
  const densities = new Float32Array(size * size);
  let maxD = 0;
  for (let py = 0; py < size; py++) {
    for (let px = 0; px < size; px++) {
      const x1 = (px / (size - 1)) * 3.2 - 1.6;
      const x2 = 1.6 - (py / (size - 1)) * 3.2;
      let density = 0;
      for (let i = 0; i < nZ; i++) {
        const z = -2 + 4 * i / (nZ - 1);
        const c = fPhi(z);
        const dx = x1 - c.x, dy = x2 - c.y;
        density += Math.exp(-(dx * dx + dy * dy) / (2 * SIGMA * SIGMA)) * Math.exp(-z * z / 2);
      }
      densities[py * size + px] = density;
      if (density > maxD) maxD = density;
    }
  }
  for (let py = 0; py < size; py++) {
    for (let px = 0; px < size; px++) {
      const idx = py * size + px;
      const t = Math.pow(densities[idx] / maxD, 0.5);
      const r = Math.round(42 + (255 - 42) * t);
      const g = Math.round(13 + (233 - 13) * t);
      const b = Math.round(8 + (196 - 8) * t);
      const pi = idx * 4;
      imgData.data[pi] = r;
      imgData.data[pi + 1] = g;
      imgData.data[pi + 2] = b;
      imgData.data[pi + 3] = 255;
    }
  }
  ctx.putImageData(imgData, 0, 0);
  const tex = new THREE.CanvasTexture(canvas);
  tex.needsUpdate = true;
  return tex;
}

const marginalTex = createMarginalTexture();
const marginalMat = new THREE.MeshBasicMaterial({
  map: marginalTex, transparent: true, opacity: 0, side: THREE.DoubleSide
});
const marginalPlane = new THREE.Mesh(new THREE.PlaneGeometry(3.2, 3.2), marginalMat);
marginalPlane.position.set(3.8, 0, 0);
marginalPlane.rotation.y = -Math.PI / 4;
scene.add(marginalPlane);

// --- Projected curve on marginal plane ---
const projPts = [];
for (let i = 0; i <= 100; i++) {
  const z = -2 + 4 * i / 100;
  const c = fPhi(z);
  projPts.push(new THREE.Vector3(c.x, c.y, 0));
}
const projCurve = new THREE.CatmullRomCurve3(projPts);
const projTube = new THREE.TubeGeometry(projCurve, 100, 0.02, 8, false);
const projMesh = new THREE.Mesh(projTube, new THREE.MeshBasicMaterial({ color: TEAL, transparent: true, opacity: 0 }));
projMesh.position.copy(marginalPlane.position);
projMesh.rotation.copy(marginalPlane.rotation);
projMesh.translateZ(0.01);
scene.add(projMesh);

// Projected dots on marginal
const projDot1 = new THREE.Mesh(new THREE.SphereGeometry(0.045, 12, 12), new THREE.MeshBasicMaterial({ color: TEAL, transparent: true, opacity: 0 }));
projDot1.position.set(marginalPlane.position.x + c1.x * Math.cos(-Math.PI/4), c1.y, marginalPlane.position.z + c1.x * Math.sin(-Math.PI/4));
scene.add(projDot1);
const projDot2 = new THREE.Mesh(new THREE.SphereGeometry(0.045, 12, 12), new THREE.MeshBasicMaterial({ color: TEAL, transparent: true, opacity: 0 }));
projDot2.position.set(marginalPlane.position.x + c2.x * Math.cos(-Math.PI/4), c2.y, marginalPlane.position.z + c2.x * Math.sin(-Math.PI/4));
scene.add(projDot2);

// --- Gray annotation arrow ---
const arrowStart = new THREE.Vector3(1.8, -1.8, 1.5);
const arrowEnd = new THREE.Vector3(3.2, -1.2, 0.5);
const arrowLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([arrowStart, arrowEnd]),
  new THREE.LineBasicMaterial({ color: GRAY, linewidth: 2 })
);
scene.add(arrowLine);
const arrowDir = arrowEnd.clone().sub(arrowStart).normalize();
const arrowCone = new THREE.Mesh(
  new THREE.ConeGeometry(0.06, 0.2, 8),
  new THREE.MeshBasicMaterial({ color: GRAY })
);
arrowCone.position.copy(arrowEnd);
arrowCone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), arrowDir);
scene.add(arrowCone);

// --- Posterior curve ---
const posteriorLine = new THREE.Line(
  new THREE.BufferGeometry(),
  new THREE.LineBasicMaterial({ color: TEAL, linewidth: 2 })
);
scene.add(posteriorLine);

let obsPos = new THREE.Vector3(0.5, 0.8, 0);
function computePosterior(obs) {
  const pts = [];
  const n = 100;
  const s2 = 2 * SIGMA * SIGMA;
  let maxP = 0;
  const vals = [];
  for (let i = 0; i <= n; i++) {
    const z = -2 + 4 * i / n;
    const c = fPhi(z);
    const dx = obs.x - c.x, dy = obs.y - c.y;
    const p = Math.exp(-(dx * dx + dy * dy) / s2) * Math.exp(-z * z / 2);
    vals.push(p);
    if (p > maxP) maxP = p;
  }
  for (let i = 0; i <= n; i++) {
    const z = -2 + 4 * i / n;
    const h = (vals[i] / maxP) * 0.8;
    pts.push(new THREE.Vector3(0, -1.6 + h, z));
  }
  return pts;
}

function updatePosterior() {
  const pts = computePosterior(obsPos);
  posteriorLine.geometry.dispose();
  posteriorLine.geometry = new THREE.BufferGeometry().setFromPoints(pts);
}
updatePosterior();

// --- Observation marker ---
const obsMarker = new THREE.Mesh(
  new THREE.SphereGeometry(0.06, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0x2288aa })
);
obsMarker.position.copy(obsPos);
scene.add(obsMarker);
registerInteractive(obsMarker, {
  title: 'Observation x',
  body: 'Drag this marker in the x1-x2 plane to probe the posterior Pr(z|x). Near the fold of the manifold, the posterior becomes broad or bimodal.',
  tooltip: 'Drag to probe posterior Pr(z|x)'
});

// --- Sweep plane for marginalize animation ---
const sweepPlane = new THREE.Mesh(
  new THREE.PlaneGeometry(3.2, 3.2),
  new THREE.MeshBasicMaterial({ color: TEAL, transparent: true, opacity: 0.25, side: THREE.DoubleSide })
);
sweepPlane.visible = false;
scene.add(sweepPlane);

// --- Camera ---
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  heightFraction: 0.72,
  target: [1.0, 0, 0]
});

// --- Labels ---
addLabel('<i>x</i><sub>1</sub>', new THREE.Vector3(0, 1.85, -1.8), { fontSize: '15px', bold: true });
addLabel('<i>x</i><sub>2</sub>', new THREE.Vector3(-1.85, 0.3, -1.8), { fontSize: '15px', bold: true });
addLabel('<i>z</i>', new THREE.Vector3(-0.3, -1.85, 0.5), { fontSize: '15px', bold: true });
addLabel('Pr(<b>x</b>, <i>z</i> | φ)', new THREE.Vector3(1.2, -2.0, 1.8), { fontSize: '13px' });
addLabel('<i>x</i><sub>1</sub>', new THREE.Vector3(4.6, 1.7, -0.8), { fontSize: '13px', bold: true });
addLabel('<i>x</i><sub>2</sub>', new THREE.Vector3(4.8, -0.3, -1.2), { fontSize: '13px', bold: true });
addLabel('Pr(<b>x</b> | φ)', new THREE.Vector3(4.5, -1.9, -0.5), { fontSize: '13px' });
addLabel('Marginalize over<br>latent variable, <i>z</i>', new THREE.Vector3(2.5, -2.2, 1.0), { fontSize: '12px' });

// --- UI wiring ---
const sliderZ = document.getElementById('latentZ');
sliderZ.addEventListener('input', () => {
  const z = parseFloat(sliderZ.value);
  updateActiveSlice(z);
});

// --- Marginalize animation ---
let marginalizeAnim = null;
document.getElementById('btnMarginalize').addEventListener('click', () => {
  if (marginalizeAnim) return;
  marginalizeAnim = { t: 0, duration: 3.0 };
  sweepPlane.visible = true;
  marginalMat.opacity = 0;
  projMesh.material.opacity = 0;
  projDot1.material.opacity = 0;
  projDot2.material.opacity = 0;
});

// --- Drag observation ---
let isDragging = false;
const dragPlane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);
const raycaster = new THREE.Raycaster();
const mouse = new THREE.Vector2();
const intersectPt = new THREE.Vector3();

canvas.addEventListener('pointerdown', (e) => {
  const rect = canvas.getBoundingClientRect();
  mouse.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  mouse.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  raycaster.setFromCamera(mouse, camera);
  const hits = raycaster.intersectObject(obsMarker);
  if (hits.length > 0) {
    isDragging = true;
    controls.enabled = false;
    canvas.style.cursor = 'grabbing';
  }
});

canvas.addEventListener('pointermove', (e) => {
  if (!isDragging) return;
  const rect = canvas.getBoundingClientRect();
  mouse.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  mouse.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  raycaster.setFromCamera(mouse, camera);
  if (raycaster.ray.intersectPlane(dragPlane, intersectPt)) {
    obsPos.x = Math.max(-1.5, Math.min(1.5, intersectPt.x));
    obsPos.y = Math.max(-1.5, Math.min(1.5, intersectPt.y));
    obsMarker.position.copy(obsPos);
    updatePosterior();
  }
});

canvas.addEventListener('pointerup', () => {
  if (isDragging) {
    isDragging = false;
    controls.enabled = true;
    canvas.style.cursor = 'grab';
  }
});

document.getElementById('btnResetObs').addEventListener('click', () => {
  obsPos.set(0.5, 0.8, 0);
  obsMarker.position.copy(obsPos);
  updatePosterior();
});

// --- Animation additions ---
const _origAnimate = animate;
let _lastTime = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = (now - _lastTime) / 1000;
  _lastTime = now;

  if (marginalizeAnim) {
    marginalizeAnim.t += dt;
    const progress = Math.min(marginalizeAnim.t / marginalizeAnim.duration, 1);
    const z = -2 + 4 * progress;
    sweepPlane.position.set(0, 0, z);
    sweepPlane.visible = progress < 1;
    marginalMat.opacity = progress;
    projMesh.material.opacity = progress;
    projDot1.material.opacity = progress;
    projDot2.material.opacity = progress;
    if (progress >= 1) {
      marginalizeAnim = null;
      sweepPlane.visible = false;
    }
  }
}
tick();

// --- Demo steps ---
const demoSteps = [
  { title: 'Joint distribution', narration: 'The box holds Pr(x,z|φ): each z slice shows a Gaussian conditional Pr(x|z,φ) whose center follows the teal decoder curve.', state: { latentZ: -1.2 } },
  { title: 'Move the latent slice', narration: 'Drag z from -1.2 to +1.2. The highlighted conditional blob travels along the arc.', state: { latentZ: 1.2 } },
  { title: 'Probe the posterior', narration: 'Drag the observation marker to the top fold of the arc. The posterior over z widens.', state: { latentZ: 0 } },
  { title: 'Marginalize', narration: 'Play the marginalization sweep: all slices integrate along z, collapsing into the 2D banana-shaped Pr(x|φ).', state: { latentZ: 0 } }
];

window.goToStep = function(idx) {
  if (idx < 0 || idx >= demoSteps.length) return;
  const step = demoSteps[idx];
  if (step.state.latentZ !== undefined) {
    sliderZ.value = step.state.latentZ;
    updateActiveSlice(step.state.latentZ);
  }
  if (idx === 3) document.getElementById('btnMarginalize').click();
  showPopup(step.title, step.narration);
};
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

