renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));

const state = {
  rotationCamera2: 0,
  translationCamera2: 0,
  activeStep: 0,
  tween: null
};

const BLACK = 0x111318;
const SOFT_BLACK = 0x1b1d22;
const RED = 0xff1010;
const GREEN = 0x22e000;
const BLUE = 0x2878ff;
const CYAN = 0x60f3ef;
const MAGENTA = 0xff76b7;
const WHITE = 0xffffff;

const fixedGroup = new THREE.Group();
const dynamicGroup = new THREE.Group();
scene.add(fixedGroup, dynamicGroup);

const worldUp = new THREE.Vector3(0, 1, 0);
const C1 = new THREE.Vector3(-4.65, -1.65, -0.12);
