// @FIGURE_CODE_BEGIN
/* === GEOMETRY SPEC ===
// box wireframe → LineSegments, brown #6b3a1f, box [-1.6,1.6]x[-1.6,1.6]x[-2,2]
// slice plane 1 → PlaneGeometry(3.2,3.2) at z=-1.0, opacity 0.97, dark maroon #2a0d08, cream Gaussian blob
// slice plane 2 → PlaneGeometry(3.2,3.2) at z=0.7, opacity 0.97, dark maroon, cream Gaussian blob
// decoder manifold → TubeGeometry(r=0.03) along f_phi(z), teal #5bc8c8
// dashed segment → Line+LineDashedMaterial between two sample dots, teal
// sample dot 1 → SphereGeometry(0.06) at f_phi(-1.2), teal
// sample dot 2 → SphereGeometry(0.06) at f_phi(0.8), teal
// teal downward arrow → TubeGeometry curving down from manifold end + cone arrowhead
// marginal plane → PlaneGeometry(3.4,3.4) at x=5.5, z=0, full opacity, banana texture
// projected curve → TubeGeometry on marginal plane, teal
// projected dots → SphereGeometry(0.05) on marginal plane, teal
// projected downward arrow → TubeGeometry + cone on marginal plane, teal
// gray annotation arrow → Line+ConeGeometry, #b0b0b0, from box to marginal
// posterior curve (hidden) → Line along z at bottom of box, teal
// observation marker (hidden) → SphereGeometry(0.07), teal
// sweep plane (hidden) → PlaneGeometry(3.2,3.2), teal translucent
*/

const BROWN = 0x6b3a1f;
const MAROON = 0x2a0d08;
const CREAM = 0xffe9c4;
const TEAL = 0x5bc8c8;
const GRAY = 0xb0b0b0;
const SIGMA = 0.28;

function fPhi(z) {
  return { x: 1.25 * Math.cos(0.85 * z), y: 1.25 * Math.sin(0.85 * z) - 0.2 };
}

// --- Box wireframe ---
const boxMin = new THREE.Vector3(-1.6, -1.6, -2);
const boxMax = new THREE.Vector3(1.6, 1.6, 2);
const corners = [
  [boxMin.x, boxMin.y, boxMin.z], [boxMax.x, boxMin.y, boxMin.z],
  [boxMax.x, boxMax.y, boxMin.z], [boxMin.x, boxMax.y, boxMin.z],
  [boxMin.x, boxMin.y, boxMax.z], [boxMax.x, boxMin.y, boxMax.z],
  [boxMax.x, boxMax.y, boxMax.z], [boxMin.x, boxMax.y, boxMax.z]
];
const edgePairs = [[0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7],[7,4],[0,4],[1,5],[2,6],[3,7]];
const boxEdges = [];
for (const [a, b] of edgePairs) {
  boxEdges.push(new THREE.Vector3(...corners[a]), new THREE.Vector3(...corners[b]));
}
const boxLine = new THREE.LineSegments(
  new THREE.BufferGeometry().setFromPoints(boxEdges),
  new THREE.LineBasicMaterial({ color: BROWN })
);
scene.add(boxLine);

// --- Gaussian texture helper ---
function createGaussianTexture(cx, cy, sigma, size = 256) {
  const canvas = document.createElement('canvas');
  canvas.width = size; canvas.height = size;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#2a0d08';
  ctx.fillRect(0, 0, size, size);
  const px = ((cx + 1.6) / 3.2) * size;
  const py = size - ((cy + 1.6) / 3.2) * size;
  const sigmaPx = (sigma / 3.2) * size;
  const r = sigmaPx * 4.5;
  const grad = ctx.createRadialGradient(px, py, 0, px, py, r);
  grad.addColorStop(0, 'rgba(255,252,240,1)');
  grad.addColorStop(0.15, 'rgba(255,233,196,0.95)');
  grad.addColorStop(0.35, 'rgba(212,132,90,0.8)');
  grad.addColorStop(0.6, 'rgba(107,42,21,0.5)');
  grad.addColorStop(1, 'rgba(42,13,8,0)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, size, size);
  const tex = new THREE.CanvasTexture(canvas);
  tex.needsUpdate = true;
  return tex;
}

// --- Two slice planes (high opacity) ---
const sliceZs = [-1.0, 0.7];
const slicePlanes = [];
for (const z of sliceZs) {
  const c = fPhi(z);
  const tex = createGaussianTexture(c.x, c.y, SIGMA);
  const mat = new THREE.MeshBasicMaterial({
    map: tex, transparent: true, opacity: 0.97, side: THREE.DoubleSide, depthWrite: true
  });
  const plane = new THREE.Mesh(new THREE.PlaneGeometry(3.2, 3.2), mat);
  plane.position.set(0, 0, z);
  scene.add(plane);
  slicePlanes.push({ mesh: plane, z });
}

// Active slice highlight
let activeSliceIdx = 0;
function updateActiveSlice(zVal) {
  let best = 0, bestDist = Infinity;
  slicePlanes.forEach((s, i) => {
    const d = Math.abs(s.z - zVal);
    if (d < bestDist) { bestDist = d; best = i; }
  });
  slicePlanes.forEach((s, i) => {
    s.mesh.material.opacity = (i === best) ? 1.0 : 0.85;
  });
  activeSliceIdx = best;
}
updateActiveSlice(-1.2);

// --- Decoder manifold (solid parts) ---
const manifoldPts = [];
for (let i = 0; i <= 200; i++) {
  const z = -2 + 4 * i / 200;
  const c = fPhi(z);
  manifoldPts.push(new THREE.Vector3(c.x, c.y, z));
}
const manifoldCurve = new THREE.CatmullRomCurve3(manifoldPts);
const tubeGeom = new THREE.TubeGeometry(manifoldCurve, 200, 0.03, 8, false);
const manifoldMesh = new THREE.Mesh(tubeGeom, new THREE.MeshBasicMaterial({ color: TEAL }));
scene.add(manifoldMesh);

// --- Sample dots ---
const dot1Z = -1.2, dot2Z = 0.8;
const c1 = fPhi(dot1Z), c2 = fPhi(dot2Z);
const dot1 = new THREE.Mesh(new THREE.SphereGeometry(0.06, 16, 16), new THREE.MeshBasicMaterial({ color: TEAL }));
dot1.position.set(c1.x, c1.y, dot1Z);
scene.add(dot1);
const dot2 = new THREE.Mesh(new THREE.SphereGeometry(0.06, 16, 16), new THREE.MeshBasicMaterial({ color: TEAL }));
dot2.position.set(c2.x, c2.y, dot2Z);
scene.add(dot2);

// --- Dashed arc between dots ---
const arcPts = [];
const arcN = 60;
for (let i = 0; i <= arcN; i++) {
  const t = i / arcN;
  const x = c1.x + (c2.x - c1.x) * t;
  const y = c1.y + (c2.y - c1.y) * t + 0.45 * Math.sin(Math.PI * t);
  const z = dot1Z + (dot2Z - dot1Z) * t;
  arcPts.push(new THREE.Vector3(x, y, z));
}
const arcGeom = new THREE.BufferGeometry().setFromPoints(arcPts);
const arcMat = new THREE.LineDashedMaterial({ color: TEAL, dashSize: 0.12, gapSize: 0.08 });
const arcLine = new THREE.Line(arcGeom, arcMat);
arcLine.computeLineDistances();
scene.add(arcLine);

// --- Teal downward arrow (from manifold end, curving down) ---
const arrowCurvePts = [];
const endC = fPhi(2.0);
for (let i = 0; i <= 40; i++) {
  const t = i / 40;
  const z = 2.0;
  const x = endC.x + t * 0.5;
  const y = endC.y - t * t * 2.5;
  arrowCurvePts.push(new THREE.Vector3(x, y, z));
}
const arrowCurve = new THREE.CatmullRomCurve3(arrowCurvePts);
const arrowTubeGeom = new THREE.TubeGeometry(arrowCurve, 40, 0.025, 8, false);
const arrowTube = new THREE.Mesh(arrowTubeGeom, new THREE.MeshBasicMaterial({ color: TEAL }));
scene.add(arrowTube);
const arrowEndPt = arrowCurvePts[arrowCurvePts.length - 1];
const arrowPrevPt = arrowCurvePts[arrowCurvePts.length - 3];
const arrowDir = arrowEndPt.clone().sub(arrowPrevPt).normalize();
const arrowHead = new THREE.Mesh(
  new THREE.ConeGeometry(0.07, 0.22, 8),
  new THREE.MeshBasicMaterial({ color: TEAL })
);
arrowHead.position.copy(arrowEndPt);
arrowHead.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), arrowDir);
scene.add(arrowHead);

// --- Marginal density texture (banana) ---
function createMarginalTexture(size = 256) {
  const canvas = document.createElement('canvas');
  canvas.width = size; canvas.height = size;
  const ctx = canvas.getContext('2d');
  const imgData = ctx.createImageData(size, size);
  const nZ = 100;
  const densities = new Float32Array(size * size);
  let maxD = 0;
  for (let py = 0; py < size; py++) {
    for (let px = 0; px < size; px++) {
      const x1 = (px / (size - 1)) * 3.4 - 1.7;
      const x2 = 1.7 - (py / (size - 1)) * 3.4;
      let density = 0;
      for (let i = 0; i < nZ; i++) {
        const z = -2 + 4 * i / (nZ - 1);
        const c = fPhi(z);
        const dx = x1 - c.x, dy = x2 - c.y;
        density += Math.exp(-(dx * dx + dy * dy) / (2 * SIGMA * SIGMA)) * Math.exp(-z * z / 2);
      }
      densities[py * size + px] = density;
      if (density > maxD) maxD = density;
    }
  }
  for (let py = 0; py < size; py++) {
    for (let px = 0; px < size; px++) {
      const idx = py * size + px;
      const t = Math.pow(densities[idx] / maxD, 0.45);
      const r = Math.round(42 + (255 - 42) * t);
      const g = Math.round(13 + (248 - 13) * t);
      const b = Math.round(8 + (235 - 8) * t);
      const pi = idx * 4;
      imgData.data[pi] = r;
      imgData.data[pi + 1] = g;
      imgData.data[pi + 2] = b;
      imgData.data[pi + 3] = 255;
    }
  }
  ctx.putImageData(imgData, 0, 0);
  const tex = new THREE.CanvasTexture(canvas);
  tex.needsUpdate = true;
  return tex;
}

// --- Marginal plane at x=5.5 (clear gap from box) ---
const MARGINAL_X = 5.5;
const marginalTex = createMarginalTexture();
const marginalMat = new THREE.MeshBasicMaterial({
  map: marginalTex, transparent: false, side: THREE.DoubleSide
});
const marginalPlane = new THREE.Mesh(new THREE.PlaneGeometry(3.4, 3.4), marginalMat);
marginalPlane.position.set(MARGINAL_X, 0, 0);
scene.add(marginalPlane);

// --- Projected curve on marginal plane ---
const projCurvePts = [];
for (let i = 0; i <= 100; i++) {
  const z = -2 + 4 * i / 100;
  const c = fPhi(z);
  projCurvePts.push(new THREE.Vector3(MARGINAL_X + c.x * 0.85, c.y * 0.85, 0.02));
}
const projCurve3 = new THREE.CatmullRomCurve3(projCurvePts);
const projTubeGeom = new THREE.TubeGeometry(projCurve3, 100, 0.02, 8, false);
const projMesh = new THREE.Mesh(projTubeGeom, new THREE.MeshBasicMaterial({ color: TEAL }));
scene.add(projMesh);

// Projected dots on marginal
const projDot1 = new THREE.Mesh(new THREE.SphereGeometry(0.05, 12, 12), new THREE.MeshBasicMaterial({ color: TEAL }));
projDot1.position.set(MARGINAL_X + c1.x * 0.85, c1.y * 0.85, 0.03);
scene.add(projDot1);
const projDot2 = new THREE.Mesh(new THREE.SphereGeometry(0.05, 12, 12), new THREE.MeshBasicMaterial({ color: TEAL }));
projDot2.position.set(MARGINAL_X + c2.x * 0.85, c2.y * 0.85, 0.03);
scene.add(projDot2);

// Projected downward arrow on marginal plane
const projEndC = fPhi(2.0);
const projArrowPts = [];
for (let i = 0; i <= 30; i++) {
  const t = i / 30;
  const x = projEndC.x * 0.85 + t * 0.35;
  const y = projEndC.y * 0.85 - t * t * 2.0;
  projArrowPts.push(new THREE.Vector3(MARGINAL_X + x, y, 0.02));
}
const projArrowCurve = new THREE.CatmullRomCurve3(projArrowPts);
const projArrowTubeGeom = new THREE.TubeGeometry(projArrowCurve, 30, 0.02, 8, false);
const projArrowTube = new THREE.Mesh(projArrowTubeGeom, new THREE.MeshBasicMaterial({ color: TEAL }));
scene.add(projArrowTube);
const projArrowEnd = projArrowPts[projArrowPts.length - 1];
const projArrowPrev = projArrowPts[projArrowPts.length - 3];
const projArrowDir = projArrowEnd.clone().sub(projArrowPrev).normalize();
const projArrowHead = new THREE.Mesh(
  new THREE.ConeGeometry(0.06, 0.2, 8),
  new THREE.MeshBasicMaterial({ color: TEAL })
);
projArrowHead.position.copy(projArrowEnd);
projArrowHead.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), projArrowDir);
scene.add(projArrowHead);

// --- Gray annotation arrow ---
const grayArrowStart = new THREE.Vector3(2.0, -2.2, 0.5);
const grayArrowEnd = new THREE.Vector3(4.2, -2.4, 0.2);
const grayArrowLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([grayArrowStart, grayArrowEnd]),
  new THREE.LineBasicMaterial({ color: GRAY })
);
scene.add(grayArrowLine);
const grayDir = grayArrowEnd.clone().sub(grayArrowStart).normalize();
const grayCone = new THREE.Mesh(
  new THREE.ConeGeometry(0.06, 0.2, 8),
  new THREE.MeshBasicMaterial({ color: GRAY })
);
grayCone.position.copy(grayArrowEnd);
grayCone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), grayDir);
scene.add(grayCone);

// --- Posterior curve (HIDDEN by default) ---
const posteriorLine = new THREE.Line(
  new THREE.BufferGeometry(),
  new THREE.LineBasicMaterial({ color: TEAL })
);
posteriorLine.visible = false;
scene.add(posteriorLine);

let obsPos = new THREE.Vector3(0.5, 0.8, 0);
function computePosterior(obs) {
  const pts = [];
  const n = 100;
  const s2 = 2 * SIGMA * SIGMA;
  let maxP = 0;
  const vals = [];
  for (let i = 0; i <= n; i++) {
    const z = -2 + 4 * i / n;
    const c = fPhi(z);
    const dx = obs.x - c.x, dy = obs.y - c.y;
    const p = Math.exp(-(dx * dx + dy * dy) / s2) * Math.exp(-z * z / 2);
    vals.push(p);
    if (p > maxP) maxP = p;
  }
  for (let i = 0; i <= n; i++) {
    const z = -2 + 4 * i / n;
    const h = (vals[i] / maxP) * 0.8;
    pts.push(new THREE.Vector3(0, -1.6 + h, z));
  }
  return pts;
}

function updatePosterior() {
  const pts = computePosterior(obsPos);
  posteriorLine.geometry.dispose();
  posteriorLine.geometry = new THREE.BufferGeometry().setFromPoints(pts);
}
updatePosterior();

// --- Observation marker (HIDDEN by default) ---
const obsMarker = new THREE.Mesh(
  new THREE.SphereGeometry(0.07, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0x2288aa })
);
obsMarker.position.copy(obsPos);
obsMarker.visible = false;
scene.add(obsMarker);
registerInteractive(obsMarker, {
  title: 'Observation x',
  body: 'Drag this marker in the x1-x2 plane to probe the posterior Pr(z|x). Near the fold of the manifold, the posterior becomes broad or bimodal.',
  tooltip: 'Drag to probe posterior Pr(z|x)'
});

// --- Sweep plane for marginalize animation ---
const sweepPlane = new THREE.Mesh(
  new THREE.PlaneGeometry(3.2, 3.2),
  new THREE.MeshBasicMaterial({ color: TEAL, transparent: true, opacity: 0.2, side: THREE.DoubleSide })
);
sweepPlane.visible = false;
scene.add(sweepPlane);

// --- Camera (higher elevation to show top face) ---
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 32, z: 32 },
  heightFraction: 0.72,
  target: [2.0, 0, 0]
});

// --- Labels ---
addLabel('<i>x</i><sub>1</sub>', new THREE.Vector3(0.2, 1.9, -1.8), { fontSize: '16px', bold: true });
addLabel('<i>x</i><sub>2</sub>', new THREE.Vector3(-1.9, 0.3, -1.8), { fontSize: '16px', bold: true });
addLabel('<i>z</i>', new THREE.Vector3(-0.8, -1.9, 1.2), { fontSize: '16px', bold: true });
addLabel('Pr(<b>x</b>, <i>z</i> | φ)', new THREE.Vector3(1.8, -2.2, 1.8), { fontSize: '14px' });
addLabel('<i>x</i><sub>1</sub>', new THREE.Vector3(MARGINAL_X + 0.3, 1.9, 0), { fontSize: '14px', bold: true });
addLabel('<i>x</i><sub>2</sub>', new THREE.Vector3(MARGINAL_X + 1.8, -1.6, 0), { fontSize: '14px', bold: true });
addLabel('Pr(<b>x</b> | φ)', new THREE.Vector3(MARGINAL_X + 0.5, -2.2, 0), { fontSize: '14px' });
addLabel('Marginalize over<br>latent variable, <i>z</i>', new THREE.Vector3(3.2, -2.8, 0.3), { fontSize: '12px' });

// --- UI wiring ---
const sliderZ = document.getElementById('latentZ');
sliderZ.addEventListener('input', () => {
  const z = parseFloat(sliderZ.value);
  updateActiveSlice(z);
});

// --- Marginalize animation ---
let marginalizeAnim = null;
document.getElementById('btnMarginalize').addEventListener('click', () => {
  if (marginalizeAnim) return;
  marginalizeAnim = { t: 0, duration: 2.5 };
  sweepPlane.visible = true;
});

// --- Show/hide posterior ---
let posteriorVisible = false;
document.getElementById('btnShowPosterior').addEventListener('click', () => {
  posteriorVisible = !posteriorVisible;
  obsMarker.visible = posteriorVisible;
  posteriorLine.visible = posteriorVisible;
  document.getElementById('btnShowPosterior').textContent = posteriorVisible ? 'Hide posterior' : 'Show posterior';
  document.getElementById('btnShowPosterior').classList.toggle('active', posteriorVisible);
});

// --- Drag observation ---
let isDragging = false;
const dragPlane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);
const raycaster = new THREE.Raycaster();
const mouse = new THREE.Vector2();
const intersectPt = new THREE.Vector3();

canvas.addEventListener('pointerdown', (e) => {
  if (!posteriorVisible) return;
  const rect = canvas.getBoundingClientRect();
  mouse.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  mouse.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  raycaster.setFromCamera(mouse, camera);
  const hits = raycaster.intersectObject(obsMarker);
  if (hits.length > 0) {
    isDragging = true;
    controls.enabled = false;
    canvas.style.cursor = 'grabbing';
  }
});

canvas.addEventListener('pointermove', (e) => {
  if (!isDragging) return;
  const rect = canvas.getBoundingClientRect();
  mouse.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  mouse.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  raycaster.setFromCamera(mouse, camera);
  if (raycaster.ray.intersectPlane(dragPlane, intersectPt)) {
    obsPos.x = Math.max(-1.5, Math.min(1.5, intersectPt.x));
    obsPos.y = Math.max(-1.5, Math.min(1.5, intersectPt.y));
    obsMarker.position.copy(obsPos);
    updatePosterior();
  }
});

canvas.addEventListener('pointerup', () => {
  if (isDragging) {
    isDragging = false;
    controls.enabled = true;
    canvas.style.cursor = 'grab';
  }
});

// --- Animation tick ---
let _lastTime = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = (now - _lastTime) / 1000;
  _lastTime = now;

  if (marginalizeAnim) {
    marginalizeAnim.t += dt;
    const progress = Math.min(marginalizeAnim.t / marginalizeAnim.duration, 1);
    const z = -2 + 4 * progress;
    sweepPlane.position.set(0, 0, z);
    sweepPlane.visible = progress < 1;
    if (progress >= 1) {
      marginalizeAnim = null;
      sweepPlane.visible = false;
    }
  }
}
tick();

// --- Demo steps ---
const demoSteps = [
  { title: 'Joint distribution', narration: 'The box holds Pr(x,z|φ): each z slice shows a Gaussian conditional Pr(x|z,φ) whose center follows the teal decoder curve. The data live on a curved 1D manifold, not the full volume.', state: { latentZ: -1.2 } },
  { title: 'Move the latent slice', narration: 'Drag z from -1.2 to +1.2. The highlighted conditional blob travels along the arc and rotates, illustrating the nonlinear warping f_phi(z).', state: { latentZ: 1.2 } },
  { title: 'Probe the posterior', narration: 'Click "Show posterior" then drag the observation marker to the top fold of the arc. The posterior over z widens / splits because two latent values explain the same x.', state: { latentZ: 0 } },
  { title: 'Marginalize', narration: 'Play the marginalization sweep: all slices integrate along z, collapsing the joint into the 2D banana-shaped Pr(x|φ) on the right — the intractable marginal that motivates variational inference.', state: { latentZ: 0 } }
];

window.goToStep = function(idx) {
  if (idx < 0 || idx >= demoSteps.length) return;
  const step = demoSteps[idx];
  if (step.state.latentZ !== undefined) {
    sliderZ.value = step.state.latentZ;
    updateActiveSlice(step.state.latentZ);
  }
  if (idx === 2 && !posteriorVisible) {
    document.getElementById('btnShowPosterior').click();
  }
  if (idx === 3) document.getElementById('btnMarginalize').click();
  showPopup(step.title, step.narration);
};
